package palindrome

import "testing"

func TestSimplePalindrome(t *testing.T) {
	if !IsPalindrome("racecar") {
		t.Fatal("racecar must be a palindrome")
	}
}

func TestCaseInsensitive(t *testing.T) {
	if !IsPalindrome("Racecar") {
		t.Fatal("case must be ignored")
	}
}

func TestIgnoresPunctuationAndSpaces(t *testing.T) {
	if !IsPalindrome("A man, a plan, a canal: Panama") {
		t.Fatal("punctuation and spaces must be ignored")
	}
}

func TestDigitsCount(t *testing.T) {
	if !IsPalindrome("12321") {
		t.Fatal("12321 must be a palindrome")
	}
	if IsPalindrome("12345") {
		t.Fatal("12345 must not be a palindrome")
	}
}

func TestNotAPalindrome(t *testing.T) {
	if IsPalindrome("hello world") {
		t.Fatal("hello world must not be a palindrome")
	}
}

func TestEmptyAndAllPunctuationAreTriviallyPalindromes(t *testing.T) {
	if !IsPalindrome("") {
		t.Fatal("empty string must be a palindrome")
	}
	if !IsPalindrome("!!!") {
		t.Fatal("all-punctuation string must be a palindrome (no letters/digits to compare)")
	}
}

